"""Prepare an isolated material probe in memory; never write game binaries."""
import hashlib
import re
import struct
from inspect_assets import chunks, data_path, flatten, save_json
from extract_assets import payload


def material_preview(data):
    out=bytearray(data);changes=[];targets={f'COROLLA_KIT00_BODY_{x}' for x in 'ABCD'}
    for solid in flatten(chunks(data)):
        if solid['id']!='0x80134010':continue
        leaves={n['id']:n for n in flatten(solid.get('children',[]))}
        if '0x00134011' not in leaves:continue
        header=payload(data,leaves['0x00134011']);names=re.findall(rb'[!-~]{4,}',header)
        name=max(names,key=len).decode() if names else ''
        if name not in targets:continue
        ranges=payload(data,leaves['0x00134b02']);lead=len(ranges)%60
        count=struct.unpack_from('<I',ranges,lead+12)[0]
        texture_slot=struct.unpack_from('<I',ranges,lead+28)[0]
        shader_slot=struct.unpack_from('<I',ranges,lead+32)[0]
        textures=payload(data,leaves['0x00134012']);shaders=payload(data,leaves['0x00134013'])
        if count!=49671 or texture_slot*8+4>len(textures) or shader_slot*8+4>len(shaders):raise ValueError('Unexpected character material layout')
        if struct.unpack_from('<I',textures,texture_slot*8)[0]!=0x1c9637a6:raise ValueError('Character atlas differs')
        if struct.unpack_from('<I',shaders,shader_slot*8)[0]!=0x02a05578:raise ValueError('Character material is no longer DECAL')
        offset=leaves['0x00134013']['payload']+shader_slot*8
        out[offset:offset+4]=struct.pack('<I',0x0fedee40)
        changes.append({'part':name,'offset':offset,'offset_hex':hex(offset),'length':4,
                        'old_hex':'78 55 a0 02','new_hex':'40 ee ed 0f',
                        'old_material':'DECAL','new_material':'DULLPLASTIC'})
    if {c['part'] for c in changes}!=targets or len(changes)!=4:raise ValueError('Expected four unique body targets')
    if sum(a!=b for a,b in zip(data,out))!=16 or len(data)!=len(out):raise ValueError('Expected exactly 16 changed bytes')
    if chunks(data)!=chunks(out):raise ValueError('Chunk structure changed')
    return bytes(out),changes


def main():
    relative='CARS/COROLLA/GEOMETRY.BIN';data=data_path(relative).read_bytes()
    out,changes=material_preview(data)
    plan={'source':relative,'source_sha256':hashlib.sha256(data).hexdigest(),'result_sha256':hashlib.sha256(out).hexdigest(),
          'bytes_before':len(data),'bytes_after':len(out),'changed_bytes':16,'changes':changes,
          'backup':relative+'.before-material.bak','temporary':relative+'.uma-material.tmp',
          'approval_required':True,'game_must_be_closed':True,'applied':False,
          'purpose':'Isolate whether the DECAL material causes race invisibility; DULLPLASTIC is present in GLOBALB.BUN',
          'limits':'No animation, pose, texture, wheel, bounding-box, or geometry change. Outcome requires a race test.'}
    save_json('material-probe-plan.json',plan)
    for c in changes:print(c['part'],c['offset_hex'],c['old_hex'],'->',c['new_hex'])
    print('IN MEMORY ONLY: four material references, 16 changed bytes; unchanged file size',len(data))

if __name__=='__main__':main()

"""Stage an affine rescale of all Corolla collision hulls; preserve topology and layout."""
import hashlib
import json
import struct
import numpy as np
from inspect_assets import ROOT,chunks,flatten
from extract_assets import skip_words,payload

LOWER=np.array([-.35,-.29,.05])
UPPER=np.array([.65,.29,1.95])

def prepare(source):
    tree=chunks(source);container=[n for n in flatten(tree) if n['id']=='0x80034020']
    if len(container)!=1:raise ValueError('Expected one native collision container')
    children=container[0]['children'];out=bytearray(source);groups=[];allowed=[]
    if len(children)%3:raise ValueError('Incomplete collision hull group')
    for i in range(0,len(children),3):
        header,points,indices=children[i:i+3]
        if [n['id'] for n in (header,points,indices)]!=['0x00039200','0x00039201','0x00039202']:raise ValueError('Unexpected hull layout')
        raw=payload(source,header);start=skip_words(raw)
        version_a,version_b,_,_,_,count=struct.unpack_from('<6I',raw,start)
        name=raw[start+28:start+60].split(b'\0',1)[0].decode('ascii')
        if (version_a,version_b)!=(3,3) or not name.startswith('COROLLA_') or not name.endswith('_CV') or count<4 or points['size']!=count*48:raise ValueError('Unexpected Corolla hull header')
        vertices=[]
        for vertex in range(count):
            at=points['payload']+vertex*48
            if struct.unpack_from('<2I',source,at)!=(3,3):raise ValueError('Unsupported collision point record')
            vertices.append(struct.unpack_from('<3f',source,at+16))
        vertices=np.array(vertices);minimum=vertices.min(0);maximum=vertices.max(0)
        if not np.isfinite(vertices).all() or np.any(maximum-minimum<.01):raise ValueError('Degenerate collision hull')
        replacement=LOWER+(vertices-minimum)/(maximum-minimum)*(UPPER-LOWER)
        for vertex,value in enumerate(replacement):
            at=points['payload']+vertex*48+16;struct.pack_into('<3f',out,at,*value);allowed.append({'offset':at,'bytes':12})
        groups.append({'name':name,'vertices':count,'old_minimum':minimum.tolist(),'old_maximum':maximum.tolist(),'new_minimum':LOWER.tolist(),'new_maximum':UPPER.tolist(),'scale':((UPPER-LOWER)/(maximum-minimum)).tolist()})
    if len(groups)!=5 or chunks(out)!=tree:raise ValueError('Unexpected hull count or container layout changed')
    return bytes(out),groups,allowed

def main():
    path=ROOT/'CARS/COROLLA/GEOMETRY.BIN';backup=path.with_name('GEOMETRY.BIN.before-character-collision.bak')
    source=(backup if backup.exists() else path).read_bytes();candidate,groups,allowed=prepare(source)
    stage=ROOT/'modding/staged-runtime/GEOMETRY-character-collision.BIN';stage.write_bytes(candidate)
    plan={'target':str(path.relative_to(ROOT)),'candidate':str(stage.relative_to(ROOT)),'before_sha256':hashlib.sha256(source).hexdigest(),'after_sha256':hashlib.sha256(candidate).hexdigest(),'bytes':len(candidate),'groups':groups,'changed_ranges':allowed,'topology_and_layout_preserved':True,'installed':False,'limits':'Static convex hull approximation, not a ragdoll. Wheel suspension/mass/handling unchanged; gameplay stability and clearance pending.'}
    (ROOT/'modding/character-collision-plan.json').write_text(json.dumps(plan,indent=2)+'\n');print('Staged',len(groups),'hulls;',len(allowed),'vertex records;',plan['after_sha256'])

if __name__=='__main__':main()

"""Compile public default audio tables into a strict data-only runtime signature."""
import configparser
import hashlib
import json
from pathlib import Path
import struct
import subprocess
from inspect_assets import ROOT

REPO=ROOT/'modding/audio-tools/NFSU2CarSoundTuner'

def read(path):
    c=configparser.ConfigParser();c.read(path);return c

def main():
    data=REPO/'CarSoundData';engines=[];mapping=[]
    fields=[('UseDualGinsu','i'),('GinsuDecelID','i'),('AccelFromIdleID','i'),('MaxRPM','f'),('MinRPM','f'),('AEMSVol','i'),('GinsuAccelVol','i'),('AccelDeltaRPMThreshold','f'),('AEMSMixLRPM','f'),('GinsuMixLRPM','f'),('AEMSMixSRPM','f'),('GinsuMixSRPM','f'),('UnkFloat1','f'),('UnkFloat2','f'),('Unk2','i')]
    for i in range(43):
        c=read(data/'EngineData'/f'{i:02d}.ini')['EngineData'];words=[c.getint('CarID')]
        for name,kind in fields:
            value=c.getfloat(name) if kind=='f' else c.getint(name);words.append(struct.unpack('<I',struct.pack('<'+kind,value))[0])
        engines.append(words)
    paths=sorted((data/'CarDataMapping').glob('*.ini'))
    if [int(p.stem) for p in paths]!=list(range(len(paths))):raise ValueError('Noncontiguous mapping IDs')
    for path in paths:
        c=read(path)
        mapping.append([c[upgrade].getint(field) for upgrade in ['Stock','Street','Pro','Extreme'] for field in ['EngineData','ShiftPattern','TurboDataSet']])
    if any(3 in row[::3] for row in mapping):raise ValueError('Engine slot 3 is already used')
    if mapping[6][::3]!=[18,2,19,19]:raise ValueError('Unexpected Corolla mapping')
    header='/* Default numeric audio data from NFSU2CarSoundTuner; no game addresses or code. */\n#ifndef UMA_ENGINE_PROFILE_H\n#define UMA_ENGINE_PROFILE_H\n#include <stdint.h>\n'
    for name,rows in [('uma_engine_profile',engines),('uma_mapping_profile',mapping)]:
        header+=f'static const uint32_t {name}[{len(rows)}][{len(rows[0])}]={{\n'+''.join('{'+','.join(hex(x) for x in row)+'},\n' for row in rows)+'};\n'
    header+='#endif\n';(ROOT/'modding/runtime/uma_engine_profile.h').write_text(header)
    report={'source':'https://github.com/nlgxzef/NFSU2CarSoundTuner','commit':subprocess.check_output(['git','-C',str(REPO),'rev-parse','HEAD'],text=True).strip(),'engines':len(engines),'mappings':len(mapping),'corolla_mapping':6,'unused_engine_slot':3,'engine_stride':76,'mapping_stride':48,'strategy':'Require unique exact match of all numeric defaults in writable main-image data; reject altered or unsupported profiles. No executable file or instruction patch.','installed':False}
    (ROOT/'modding/engine-audio-profile.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report))

if __name__=='__main__':main()

"""Stage removal of stock and aftermarket rim meshes; preserve vehicle physics."""
import hashlib
import json
from inspect_assets import ROOT
from prepare_shared_parts import prepare


def stock_wheel(name):
    return any(token in name for token in ('_WHEEL_','_TIRE_','_TYRE_'))


def removed_part(car,name):
    if car=='COROLLA':return name not in {f'COROLLA_KIT00_BODY_{lod}' for lod in 'ABCD'}
    return stock_wheel(name)


def main():
    rows=[]
    for target in sorted((ROOT/'CARS').glob('*/GEOMETRY*.BIN')):
        backup=target.with_name(target.name+'.before-global-wheels.bak')
        source=(backup if backup.exists() else target).read_bytes()
        shared=target.parent.name=='WHEELS'
        if shared and len(source)==64:continue  # Empty wheel-list placeholder.
        if not shared and not any(token in source for token in (b'_WHEEL_',b'_TIRE_',b'_TYRE_')):continue
        output,ranges=prepare(source,None if shared else lambda name:removed_part(target.parent.name,name))
        if output==source:continue
        relative=target.relative_to(ROOT);candidate=ROOT/'modding/staged-runtime/global-wheels'/relative
        candidate.parent.mkdir(parents=True,exist_ok=True);candidate.write_bytes(output)
        rows.append({'target':str(relative),'candidate':str(candidate.relative_to(ROOT)),'backup':str(backup.relative_to(ROOT)),'bytes':len(source),'before_sha256':hashlib.sha256(source).hexdigest(),'after_sha256':hashlib.sha256(output).hexdigest(),'index_ranges':ranges})
    plan={'files':rows,'installed':False,'scope':'All named stock wheel/tire meshes and all aftermarket rims; Corolla preserves only the four character BODY LODs. Only triangle indices changed. Separate front-end TIREMASK fix is required. Collision, suspension and wheel radii untouched.'}
    (ROOT/'modding/global-wheels-plan.json').write_text(json.dumps(plan,indent=2)+'\n')
    print('Staged',len(rows),'files;',sum(len(x['index_ranges']) for x in rows),'wheel meshes; no installed files changed')


if __name__=='__main__':main()

"""Silence native car samples without changing bank programs, metadata or sample lengths."""
import hashlib
import json
from pathlib import Path
import struct
from inspect_assets import ROOT
from read_ea_sound import abk_samples

def mute_gin(source):
    if len(source)<32 or source[:4]!=b'Gnsu':raise ValueError('Unsupported GIN header')
    a,b,samples,rate=struct.unpack_from('<4I',source,16);start=32+(a+b+2)*4;size=((samples+31)//32)*19
    if not samples or not 8000<=rate<=192000 or start+size>len(source):raise ValueError('GIN payload outside file')
    out=bytearray(source);out[start:start+size]=b'\0'*size
    return bytes(out),[{'offset':start,'bytes':size,'samples':samples,'codec':'EA-XAS v0; zero histories/filter/residuals'}]

def mute_abk(source):
    records=abk_samples(source);out=bytearray(source);ranges=[];headers=[]
    for row in records:
        # Locate the existing PT header from its native relative directory entry.
        entry=row['bank_base']+20+row['index']*4;at=entry+struct.unpack_from('<i',source,entry)[0];headers.append((at,row['end']))
    for row in records:
        t=row['tags']
        if row['platform']!=0 or t.get(128)!=2 or t.get(130,1)!=1 or t.get(160,10)!=10 or 131 in t:raise ValueError('Unsupported mechanical sample codec')
        samples=t.get(133,0);start=row['bank_base']+t.get(136,-1);at=start;raw_count=0
        if not 0<samples<=10000000 or start<row['bank_base']+20:raise ValueError('Invalid EA sample bounds')
        for _ in range((samples+27)//28):
            if at>=row['bank_end']:raise ValueError('Truncated EA-XA frame')
            raw=source[at]==238;size=61 if raw else 15
            if at+size>row['bank_end']:raise ValueError('EA-XA frame outside sample bank')
            if raw:out[at+1:at+size]=b'\0'*(size-1);raw_count+=1
            else:out[at:at+size]=b'\0'*size
            at+=size
        if any(start<end and at>begin for begin,end in headers):raise ValueError('Sample overlaps a PT header')
        ranges.append({'index':row['index'],'offset':start,'bytes':at-start,'samples':samples,'raw_pcm_frames':raw_count,'codec':'EA-XA v2; raw markers retained, silent histories/residuals'})
    if abk_samples(bytes(out))!=records:raise ValueError('Bank metadata changed')
    return bytes(out),ranges

def sources():
    files=[]
    for folder in ['ENGINE','SHIFTING','TURBO','SKIDS']:files.extend(sorted((ROOT/'SOUND'/folder).glob('*.abk')))
    files.extend(sorted((ROOT/'SOUND/ENGINE').glob('*.gin')));files.extend(sorted((ROOT/'SOUND/IG_GLOBAL').glob('ROADNOISE*.abk')))
    return files

def main():
    entries=[];base=ROOT/'modding/staged-runtime/mechanical-silence'
    for target in sources():
        backup=target.with_name(target.name+'.before-uma-silence.bak');source=(backup if backup.exists() else target).read_bytes()
        candidate,ranges=(mute_gin if target.suffix.lower()=='.gin' else mute_abk)(source)
        relative=target.relative_to(ROOT);path=base/relative;path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(candidate)
        entries.append({'target':str(relative),'candidate':str(path.relative_to(ROOT)),'backup':str(backup.relative_to(ROOT)),'bytes':len(source),'before_sha256':hashlib.sha256(source).hexdigest(),'after_sha256':hashlib.sha256(candidate).hexdigest(),'sample_ranges':ranges})
    report={'files':entries,'scope':'Native engine, engine sweetener, shifting, turbo, skids and road noise for all cars; original Uma footsteps remain character-only. Music, voices, general ambience and impacts untouched.','installed':False,'gameplay_verified':False}
    (ROOT/'modding/mechanical-silence-plan.json').write_text(json.dumps(report,indent=2)+'\n');print('Staged',len(entries),'mechanical banks/GIN files;',sum(len(x['sample_ranges']) for x in entries),'sample ranges; no game files replaced')

if __name__=='__main__':main()

"""Prepare compact native geometry with sampled motion bounds; do not install it."""
import hashlib
import json
import struct
import subprocess
import numpy as np
from inspect_assets import ROOT,chunks,flatten,data_path
from extract_assets import geometry,payload
from plan_hidden_compaction import SOURCE_HASH,verify_compaction,reviewed_source
from animate_kitasan import Rig


def motion_bounds():
    rig=Rig();minimum=rig.records[:,:3].min(0).astype(float);maximum=rig.records[:,:3].max(0).astype(float)
    for name in ('idle','run'):
        with np.load(ROOT/f'modding/animation-offline-v2/{name}.npz',allow_pickle=False) as clip:
            for rotation,offset in zip(clip['rotations'],clip['offsets']):
                positions,_=rig.skin(rotation,offset);minimum=np.minimum(minimum,positions.min(0));maximum=np.maximum(maximum,positions.max(0))
    return minimum-.15,maximum+.15


def with_motion_bounds(data,minimum,maximum):
    result=bytearray(data);nodes={n['offset']:n for n in flatten(chunks(data))};fields=[]
    meshes=geometry(data,'_KIT00_BODY_')
    if {m['name'] for m in meshes}!={f'COROLLA_KIT00_BODY_{x}' for x in 'ABCD'}:raise ValueError('Unexpected bodies')
    for mesh in meshes:
        solid=nodes[mesh['solid_offset']];leaves={n['id']:n for n in flatten(solid['children'])}
        header=leaves['0x00134011'];ranges=leaves['0x00134b02'];lead=len(payload(data,ranges))%60
        for node,begin in ((header,32),(ranges,lead)):
            for delta,values in ((0,minimum),(16,maximum)):
                for axis,value in enumerate(values):
                    at=node['payload']+begin+delta+axis*4;new=struct.pack('<f',value)
                    fields.append({'part':mesh['name'],'chunk':node['id'],'offset':at,'before':data[at:at+4].hex(),'after':new.hex()});result[at:at+4]=new
    if chunks(result)!=chunks(data):raise ValueError('Bounds changed container layout')
    return bytes(result),fields


def main():
    source_path=reviewed_source();source=source_path.read_bytes()
    if hashlib.sha256(source).hexdigest()!=SOURCE_HASH:raise ValueError('Source differs from reviewed prototype')
    completed=subprocess.run([str(ROOT/'modding/runtime/compact-hidden-dry-run'),str(source_path.relative_to(ROOT))],cwd=ROOT,stdout=subprocess.PIPE,check=True,timeout=120)
    compact=completed.stdout;verify_compaction(source,compact)
    minimum,maximum=motion_bounds();candidate,fields=with_motion_bounds(compact,minimum,maximum);verified=verify_compaction(source,candidate)
    destination=ROOT/'modding/staged-runtime';destination.mkdir(exist_ok=True)
    output=destination/'GEOMETRY.BIN'
    with output.open('xb') as stream:stream.write(candidate)
    report={'source_sha256':SOURCE_HASH,'candidate_sha256':hashlib.sha256(candidate).hexdigest(),'bytes':len(candidate),'minimum':minimum.tolist(),'maximum':maximum.tolist(),'bounds_basis':'80 authored idle/run keyframes plus rest and 0.15m margin; not exhaustive runtime interpolation proof','fields':fields,'compaction':verified,'installed':False,'authorization':'User explicitly authorized all repairs after pipeline capture; executables/network remain excluded'}
    (destination/'geometry-plan.json').write_text(json.dumps(report,indent=2)+'\n')
    print(json.dumps({k:v for k,v in report.items() if k not in ('fields','compaction')}))

if __name__=='__main__':main()

"""Stage removal of shared car accessories by degenerating only triangle indices."""
import hashlib
import json
from inspect_assets import ROOT,chunks
from extract_assets import geometry

PARTS=('MIRRORS_BODY','MIRRORS_POST','MIRRORS_SUV','MIRRORS_HUMMER','SPOILER','SPOILER_HATCH','SPOILER_SUV','PLATES','EXHAUST','ROOF','BRAKES','AUDIO')

def prepare(source,include=None):
    meshes=[mesh for mesh in geometry(source,'') if include is None or include(mesh['name'])];out=bytearray(source);ranges=[]
    if not meshes:raise ValueError('Shared part file contains no supported meshes')
    for mesh in meshes:
        start=mesh['index_data_offset'];size=len(mesh['indices'])*2
        if start<0 or start+size>len(source) or len(mesh['indices'])%3:raise ValueError('Invalid triangle range')
        out[start:start+size]=b'\0'*size;ranges.append({'name':mesh['name'],'offset':start,'bytes':size,'triangles':len(mesh['indices'])//3})
    if chunks(out)!=chunks(source):raise ValueError('Chunk layout changed')
    return bytes(out),ranges

def main():
    root=ROOT/'modding/staged-runtime/shared-parts';root.mkdir(exist_ok=True);files=[]
    for part in PARTS:
        relative=f'CARS/{part}/GEOMETRY.BIN';target=ROOT/relative;backup=target.with_name('GEOMETRY.BIN.before-uma-parts.bak')
        source=(backup if backup.exists() else target).read_bytes();candidate,ranges=prepare(source)
        path=root/(part+'.BIN');path.write_bytes(candidate)
        files.append({'target':relative,'candidate':str(path.relative_to(ROOT)),'bytes':len(source),'before_sha256':hashlib.sha256(source).hexdigest(),'after_sha256':hashlib.sha256(candidate).hexdigest(),'index_ranges':ranges})
    plan={'scope':'All cars: shared mirrors/spoilers/plates/exhaust/roof/brakes/trunk-audio geometry only; main car bodies preserved','method':'Set each triangle index to zero, preserving all vertices, material ranges, sizes and alignment','files':files,'installed':False}
    (ROOT/'modding/shared-parts-plan.json').write_text(json.dumps(plan,indent=2)+'\n');print('Staged',len(files),'files;',sum(len(x['index_ranges']) for x in files),'meshes; no game files replaced')

if __name__=='__main__':main()
